using Microsoft.Extensions.DependencyInjection;
using Utils;
namespace Tests;
public class AdminPayoutRunTests(ApiFactory f):ApiTest(f)
{
    [Fact]public async Task Batch_run_is_atomic_with_audit_and_only_sweeps_approved_available_minimum_balances()
    {
        var admin=await Admin();var sellers=new List<string>();for(var i=0;i<4;i++){var user=await LoginPhone("989000010"+i);if(i==0)Assert.Equal(403,(await user.Post("/api/admin/payouts/run",new{})).Status);sellers.Add((await user.Post("/api/seller/register",new{display_name="Synthetic Batch "+i})).Json["id"]!.GetValue<string>());}
        using var scope=Factory.Services.CreateScope();var crypto=scope.ServiceProvider.GetRequiredService<EncryptDecrypt>();for(var i=0;i<4;i++){var enc=crypto.Encrypt("123456789012");await ApiFactory.DbExecAsync("UPDATE sellers SET status=@status,bank_account_enc=@enc,bank_account_last4='0000',bank_ifsc='SYNT0001234',bank_holder_name='Synthetic Holder' WHERE id=@id",new{status=i==3?"draft":"approved",enc,id=sellers[i]});}
        var r=await admin.Put("/api/admin/settings",new{payout_min_paise=1000});Assert.True(r.Status==200,r.ToString());for(var i=0;i<4;i++)await ApiFactory.DbExecAsync("INSERT INTO seller_ledger(id,seller_id,kind,amount,description,available_at,created_at)VALUES(@id,@seller,'adjustment',@amount,'Synthetic batch',DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 DAY),UTC_TIMESTAMP(6))",new{id=Guid.NewGuid(),seller=sellers[i],amount=i==2?999:2000});await ApiFactory.DbExecAsync("INSERT INTO seller_ledger(id,seller_id,kind,amount,description,available_at,created_at)VALUES(UUID(),@seller,'adjustment',-1000,'Synthetic debit',DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 DAY),UTC_TIMESTAMP(6)),(UUID(),@seller,'adjustment',5000,'Synthetic future',DATE_ADD(UTC_TIMESTAMP(6),INTERVAL 1 DAY),UTC_TIMESTAMP(6))",new{seller=sellers[0]});
        await ApiFactory.DbExecAsync("CREATE TRIGGER synthetic_batch_fail BEFORE INSERT ON audit_logs FOR EACH ROW BEGIN IF NEW.action='payout.run' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Synthetic batch rollback'; END IF; END");try{Assert.Equal(500,(await admin.Post("/api/admin/payouts/run",new{})).Status);Assert.Equal(0,await ApiFactory.DbScalarAsync<int>("SELECT COUNT(*) FROM payouts"));Assert.Equal(0,await ApiFactory.DbScalarAsync<int>("SELECT COUNT(*) FROM seller_ledger WHERE payout_id IS NOT NULL"));}finally{await ApiFactory.DbExecAsync("DROP TRIGGER synthetic_batch_fail");}
        r=await admin.Post("/api/admin/payouts/run",new{});Assert.True(r.Status==200,r.ToString());Assert.Equal(2,r.Json["created"]!.GetValue<int>());Assert.Equal(2,r.Json["items"]!.AsArray().Count);Assert.Contains(r.Json["items"]!.AsArray(),x=>x!["amount"]!.GetValue<long>()==1000);Assert.Contains(r.Json["items"]!.AsArray(),x=>x!["amount"]!.GetValue<long>()==2000);foreach(var item in r.Json["items"]!.AsArray()){Assert.Equal("9012",item!["bank"]!["account_last4"]!.GetValue<string>());Assert.Null(item["bank"]!["account_enc"]);Assert.Equal("pending",item["status"]!.GetValue<string>());}Assert.Equal(0,(await admin.Post("/api/admin/payouts/run",new{})).Json["created"]!.GetValue<int>());Assert.Equal(3,await ApiFactory.DbScalarAsync<int>("SELECT COUNT(*) FROM seller_ledger WHERE payout_id IS NULL"));
    }
}
